  [90116] = { "Fili sacri", "Ottieni dei Dawnwoven Fabric tessendo stoffa in rotoli vicino al Crusader's Loom. Torna da Taylor quando ne avrai abbastanza.", "Questo telaio è speciale. Lo sapevi? Tutti i nostri artigiani hanno fatto benedire gli attrezzi del mestiere dai nostri sommi sacerdoti.\n\nIn particolare, il telaio attira stoffe e fili sparsi destinati ai più sacri dei nostri paramenti cerimoniali. Col tempo ne raccoglieremo abbastanza per creare una nuova veste, e quei giorni sono motivo di festa, almeno per me.\n\nSe il procedimento ti incuriosisce, tessi qualche rotolo vicino al telaio e guarda la Luce all'opera.", nil, nil, 0xc5231693, 0x64619cbd, 0x049e6b14, nil, nil, "...mm" },
  [90902] = { "Riscoprire la Luce", "Cura $N1 Injured Deathguard con la tua abilità ⟦Holy Light=Luce Sacra⟧.", "È un orgoglio per me accogliere tra le nostre file <un/una> nuov<o/a> paladin<o/a> appena risort<o/a>. Mentre ritrovi il legame con la Luce, potresti notare che certe abilità che un tempo ti venivano naturali ora possono causarti un dolore considerevole, in particolare quelle che incanalano la Luce per curare te stess<o/a> o gli altri.\n\nL'unico modo per aggirare il problema è, purtroppo, attraversarlo. Come ogni muscolo atrofizzato, devi superare il dolore ed esercitare la carne perché torni a funzionare appieno.", nil, "Il dolore non è una novità per chi ha sopportato la morte, e per questo i Reietti vi resistono particolarmente bene. Il dolore ha anche un potere purificatore, che dovresti accogliere come un segno d'onore e come la prova che sei davvero ancora al servizio della Luce, nonostante la tua nuova condizione.\n\nStammi bene e cammina di nuovo nella Luce, {class}.", 0xd0181974, 0x52f98d38, 0xcb54b8cd, nil, 0x32977739, "...m." },
